// Package v26_3 contains the Java 26.3 registry and Geyser Bedrock mappings.
// The legacy java/v1 and block-converts/v1 packages retain their original targets.
package v26_3

import (
	_ "embed"
	"fmt"
	"sync"

	"neomega-blocks/catalog"
)

const JavaTargetVersion = "26.3"
const BedrockTargetVersion = "1.26.60"

// Generated by third_party/gen_resource/geyser/cmd/generate using the pinned lock.
//
//go:embed catalog.json.gz
var snapshot []byte

var open = sync.OnceValues(func() (*catalog.Catalog, error) {
	c, err := catalog.Load(snapshot)
	if err != nil {
		return nil, err
	}
	meta := c.Metadata()
	if meta.JavaVersion != JavaTargetVersion || meta.BedrockVersion != BedrockTargetVersion {
		return nil, fmt.Errorf("embedded version does not match package v26_3")
	}
	return c, nil
})

// Open returns a shared immutable catalog. Startup errors are reported to callers.
func Open() (*catalog.Catalog, error) { return open() }
